insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('8c0a9516-ea78-4659-bc9d-319fb902eb7b', 'e29d68ed-63fb-4b91-86ac-a0410a5f2477', $$krantenartikel (2015): recessie, inflatie en koersdaling van de real in Brazilië$$,
   $$economie-vwo-2017-ii-is-brazilie-uitgedanst-context1.png$$,
   $$Uit een krant (2015):
Brazilië is een belangrijke leverancier van grondstoffen. Als gevolg van een inzakking van de mondiale vraag naar grondstoffen is de Braziliaanse economie in een recessie beland. De inflatie in Brazilië is opgelopen tot 10% en de werkloosheid bedraagt inmiddels 7,5% van de beroepsbevolking, het hoogste percentage in zeven jaar. Economen verwachten dat de inflatie en de werkloosheid nog meer zullen stijgen en het overheidstekort zal toenemen.
De economische problemen worden vergroot door de koersdaling van de Braziliaanse munt, de real. Deze is sinds 1 januari 2015 ten opzichte van de Amerikaanse dollar gedaald met 31%. De dollar heeft op 1 oktober van dit jaar een waarde bereikt van 3,85 real. Door deze daling zal de inflatie nog verder oplopen en zullen buitenlandse investeerders en beleggers de waarde in dollars van hun bezittingen in Brazilië zien dalen. Braziliaanse staatsobligaties, in real genoteerd, zijn door kredietbeoordelingsbureaus beoordeeld als uiterst risicovol. Beleggers worden hierdoor afgeschrikt.$$, 'inline'),
  ('0cba6210-596e-48dd-ad20-5a3e4f68517a', 'e29d68ed-63fb-4b91-86ac-a0410a5f2477', $$rentebeleid Centrale Bank: recessie en wisselkoersdaling niet tegelijk te bestrijden$$,
   $$economie-vwo-2017-ii-is-brazilie-uitgedanst-context2.png$$,
   $$Een van de instrumenten van een Centrale Bank is het rentebeleid. De Centrale Bank van Brazilië kan hiermee niet tegelijk de recessie bestrijden en de daling van de wisselkoers afremmen.$$, 'inline'),
  ('0f7a6ec4-2cdf-4902-884f-0ec1badd9aff', 'e29d68ed-63fb-4b91-86ac-a0410a5f2477', $$Thea: situatie in Brazilië past niet bij kortetermijn-Phillipscurve$$,
   $$economie-vwo-2017-ii-is-brazilie-uitgedanst-context3.png$$,
   $$Thea bespreekt het bovenstaande artikel in de economieles. Zij beweert dat de situatie in Brazilië niet overeenkomt met het verband dat in de kortetermijn-Phillipscurve wordt voorondersteld.$$, 'inline'),
  ('d8ee3c0c-0260-423c-a18d-b2b8379854ef', '312cd7a1-6d94-41d8-ad65-3b9f000d90af', $$inleiding: alle parkeergarages in het centrum zijn van Allpark$$,
   $$economie-vwo-2017-ii-parkeerbeleid-context1.png$$,
   $$Alle parkeergarages in het centrum van een middelgrote stad zijn eigendom van de particuliere onderneming Allpark.$$, 'inline'),
  ('84df327b-7d3e-45b1-909e-928acb2d212f', '312cd7a1-6d94-41d8-ad65-3b9f000d90af', $$vraagvergelijking parkeerplaatsen Qᵥ = −2.000P + 10.000$$,
   $$economie-vwo-2017-ii-parkeerbeleid-context2.png$$,
   $$Een gemeentelijk onderzoek naar de relatie tussen parkeertarieven en de totale vraag naar parkeerplaatsen in deze parkeergarages laat zien dat deze kan worden weergegeven met de volgende vraagvergelijking:
Qᵥ = −2.000P + 10.000
waarbij:
Qᵥ = totale vraag naar parkeerplaatsen in de parkeergarages in hele uren
P = parkeertarief in euro''s per uur.$$, 'inline'),
  ('fcc115fb-a626-44fd-b3ba-125f50b0317b', '312cd7a1-6d94-41d8-ad65-3b9f000d90af', $$constante kosten € 6.000 per uur, marginale kosten € 0,80; maximale winst$$,
   $$economie-vwo-2017-ii-parkeerbeleid-context3.png$$,
   $$De constante kosten per uur zijn voor alle garages samen € 6.000. De marginale kosten van één uur parkeren door één auto bedragen steeds € 0,80. Allpark streeft naar maximale totale winst.$$, 'inline'),
  ('41e41e34-aade-47df-b1fb-72367889503f', '312cd7a1-6d94-41d8-ad65-3b9f000d90af', $$automobilisten parkeren elders; gemeente overweegt maximumtarief € 2$$,
   $$economie-vwo-2017-ii-parkeerbeleid-context4.png$$,
   $$Een groot deel van de automobilisten maakt bij dit tarief geen gebruik van de parkeergarages, maar parkeert elders in de stad. De bewoners ervaren dit als overlast. De gemeente overweegt daarom een maximumtarief van € 2 per uur in te voeren voor alle parkeergarages.$$, 'inline'),
  ('b4bdc1fd-8dfa-4c91-8ac3-5369936b5792', '312cd7a1-6d94-41d8-ad65-3b9f000d90af', $$manager Allpark: op zaterdag andere prijselasticiteit, hoger tarief$$,
   $$economie-vwo-2017-ii-parkeerbeleid-context5.png$$,
   $$De manager van Allpark kan de invoering van het maximumparkeertarief accepteren, onder voorwaarde dat hij ter compensatie op de zaterdagen een hoger tarief kan vragen: “De vergelijking uit het onderzoek geeft de gemiddelde vraag naar parkeerplaatsen over alle dagen van de week. Ik schat dat op de zaterdagen, met veel winkelpubliek, de prijselasticiteit van de vraag naar parkeerplaatsen anders is dan door de week.”$$, 'inline'),
  ('ce859b04-243b-4314-9dc6-b46dbc5b28c5', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$inleiding: imagoprobleem in de branche van tweedehandsauto's$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context1.png$$,
   $$De branche van tweedehandsauto’s heeft een groeiend imagoprobleem. De laatste tijd zijn er veel bedrijven toegetreden, die het niet zo nauw nemen met de kwaliteit van de aangeboden auto’s. De betrouwbaardere bedrijven maken in verhouding hoge kosten en moeten daarom een relatief hoge verkoopprijs vragen.$$, 'inline'),
  ('ddb7448a-e8db-47d3-87c7-8d6ac1099bcf', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$keurmerk AutoKwaliteit (AK) met garantie$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context2.png$$,
   $$Om de reputatie van de branche te verbeteren is een aantal jaren geleden bedrijfstakorganisatie AutoKwaliteit (AK) opgericht. Bij AK aangesloten autohandelaren bieden de AK-garantie: tot een half jaar na aankoop kan de koper gebreken, die bij de aankoop niet waren geconstateerd, zonder betaling laten repareren. Op deze manier moeten potentiële klanten erop kunnen vertrouwen dat ze bij een AK-autohandelaar een goede auto met een goede service krijgen.$$, 'inline'),
  ('54d90a0f-68d6-4f9e-bf18-97b4aec6690c', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$argument oprichting AK: averechtse selectie door asymmetrische informatie$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context3.png$$,
   $$Het argument bij de oprichting van AK was dat er zonder keurmerk en garantie averechtse selectie van autohandelaren zal ontstaan. Asymmetrische informatie over de kwaliteit van aangeboden auto’s speelt hierbij een belangrijke rol.$$, 'inline'),
  ('78caa742-f2f9-4dfa-805e-82c3a40b6484', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$AK als principaal, aangesloten autohandelaren als agenten; kwaliteitscontroles$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context4.png$$,
   $$Het succes van AK is afhankelijk van de betrouwbaarheid van de aangesloten autohandelaren. Autohandelaren die lid zijn van AK zijn verplicht zich te houden aan kwaliteitseisen en krijgen geregeld controle door inspecteurs van AK. Deze controles dienen ter voorkoming van een principaal-agentprobleem. AK kan hierbij gezien worden als principaal en de aangesloten autohandelaren als agenten.$$, 'inline'),
  ('a83e47b2-5f07-4d41-8590-aacee7edd90f', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$Autohandel Verpaalen overweegt lidmaatschap AK (contributie)$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context5.png$$,
   $$Autohandel Verpaalen heeft in de loop der jaren een goede reputatie opgebouwd. Als gevolg van de toestroom van genoemde nieuwkomers in de branche is het bedrijf nu echter in de rode cijfers terechtgekomen. Verpaalen hoopt met toetreding tot AK weer winst te kunnen maken. Voor het lidmaatschap geldt een basiscontributie van 3.500 euro en een contributie van 400 euro per verkochte auto. Verpaalen heeft een ruwe schatting gemaakt van de te verwachten bedrijfsgegevens, afhankelijk van de keuze om wel of niet lid te worden van AK (tabel 1).$$, 'inline'),
  ('549f8282-38ba-4305-a67f-5a831c131468', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$tabel 1: geschatte bedrijfsgegevens Verpaalen met en zonder lidmaatschap AK$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context6.png$$,
   $$Tabel 1 geschatte bedrijfsgegevens van Verpaalen
geen lidmaatschap AK | wel lidmaatschap AK
GO = −40Q + 16.000 | GO = −40Q + 18.000
TK = 7.200Q + 600.000 | TK = 7.600Q + 603.500
GO = gemiddelde omzet per jaar
TK = totale kosten per jaar
Q = afzet per jaar$$, 'inline'),
  ('a492268d-3d53-47b3-a4e2-11fdfaa33129', '1bbf7b45-0361-4851-80c9-1d9530df7391', $$één kwaliteit auto's; Verpaalen streeft naar maximale totale winst$$,
   $$economie-vwo-2017-ii-gegarandeerde-winst-context7.png$$,
   $$Verpaalen is hierbij uitgegaan van één bepaalde kwaliteit auto’s. Het bedrijf streeft naar maximale totale winst.$$, 'inline'),
  ('d345fad2-4a07-4141-8025-12f81a6bd6be', '9ea93ee7-d6e6-487d-a0a3-062051db2679', $$inleiding: dreigende deflatie in de eurozone; kwantitatieve versoepeling door de ECB$$,
   $$economie-vwo-2017-ii-deflatie-soepel-op-te-lossen-context1.png$$,
   $$In 2015 dreigde in de meeste landen van de eurozone deflatie. De Europese Centrale Bank (ECB) achtte de kans groot dat deze deflatie zou leiden tot stagnatie van de economische groei en daarmee tot verdere deflatie. In een poging om de inflatie weer te laten oplopen besloot de ECB in 2015 om de geldhoeveelheid in de eurozone te vergroten via de zogenaamde kwantitatieve versoepeling. Hiertoe kocht de ECB maandelijks voor 60 miljard euro bestaande staatsobligaties op, vooral van banken in de eurozone. Deze banken kregen hierdoor de mogelijkheid om meer krediet te verstrekken aan gezinnen en bedrijven. Bij dit stimuleringsprogramma is uitgegaan van een vaste omloopsnelheid van het geld.$$, 'inline'),
  ('0e3b72ee-b408-4548-b467-8ad29f01dd6f', '9ea93ee7-d6e6-487d-a0a3-062051db2679', $$pensioenfonds Roberts verwacht dalende rendementen door opkoop nieuwe staatsobligaties$$,
   $$economie-vwo-2017-ii-deflatie-soepel-op-te-lossen-context2.png$$,
   $$Michael Roberts is directeur van een onlangs opgericht pensioenfonds dat vooral belegt in nieuwe staatsobligaties. Er gaan geruchten dat de ECB in de nabije toekomst ook nieuw uitgegeven staatsobligaties van overheden van eurolanden wil kopen. Roberts verwacht dat als gevolg hiervan zijn fonds rekening moet houden met een daling van beleggingsrendementen: de rente als percentage van het aankoopbedrag van obligaties.$$, 'inline'),
  ('af9a26a3-81b1-4b89-8f85-0e486d0a9b2b', '9ea93ee7-d6e6-487d-a0a3-062051db2679', $$kapitaaldekkingsstelsel: moeilijker om pensioenverplichtingen te voldoen$$,
   $$economie-vwo-2017-ii-deflatie-soepel-op-te-lossen-context3.png$$,
   $$Het pensioenfonds van Roberts werkt met het kapitaaldekkingsstelsel. Als de ECB het opkoopprogramma lang blijft volhouden, verwacht Roberts dat het voor zijn fonds moeilijker zal worden om aan toekomstige pensioenverplichtingen te blijven voldoen.$$, 'inline'),
  ('6dc4f613-ea22-48b1-b416-58fce8a90865', '9ea93ee7-d6e6-487d-a0a3-062051db2679', $$econoom Milano: lagere rendementen leiden via valutamarkt tot inflatie$$,
   $$economie-vwo-2017-ii-deflatie-soepel-op-te-lossen-context4.png$$,
   $$Econoom Mario Milano van de ECB verwacht dat de verlaging van de rendementen op nieuwe staatsobligaties in de eurozone via de valutamarkt kan leiden tot oplopen van de inflatie.$$, 'inline'),
  ('11e9a173-2626-4abf-9dc3-7bd0b5b7aa79', '663bed8f-bd15-4790-b859-567143ef4e08', $$inleiding: laagconjunctuur; banken terughoudend met krediet voor innovaties$$,
   $$economie-vwo-2017-ii-innovatief-krediet-context1.png$$,
   $$In 2013 is in een land al vijf jaren achtereen sprake van laagconjunctuur. Dit heeft onder andere tot gevolg dat banken terughoudend zijn geworden bij het verlenen van krediet, in het bijzonder voor de ontwikkeling van nieuwe technieken en producten. Risico-overwegingen kunnen banken terughoudend maken om krediet te verlenen voor deze innovaties.$$, 'inline'),
  ('dc5f0edf-2900-4d63-b712-76ae17bed917', '663bed8f-bd15-4790-b859-567143ef4e08', $$pensioenfondsen richten United Credit Fund (UCF) op$$,
   $$economie-vwo-2017-ii-innovatief-krediet-context2.png$$,
   $$Drie pensioenfondsen maken in een persbericht bekend dat ze een gezamenlijke financieringsmaatschappij hebben opgericht, United Credit Fund (UCF), om dit gat in de markt op te vullen. In de statuten van UCF is vastgelegd dat UCF zich specifiek richt op kredietverlening aan bedrijven voor de ontwikkeling van innovaties. Aan het verstrekken van krediet zijn voorwaarden verbonden (zie kader).$$, 'inline'),
  ('1ad7711e-137f-4665-b0e7-e44ef9d7ab77', '663bed8f-bd15-4790-b859-567143ef4e08', $$kader: kredietvoorwaarden van UCF (a, b, c)$$,
   $$economie-vwo-2017-ii-innovatief-krediet-context3.png$$,
   $$Kredietvoorwaarden van UCF
a UCF eist onderpanden in de vorm van reeds verkregen patenten en andere (vaste) activa.
b Een krediet bedraagt maximaal 5 miljoen euro.
c Ondernemingen kunnen met het krediet van UCF 40% van de ontwikkelingskosten van een innovatie financieren. Als er meerdere ondernemingen samenwerken in de ontwikkeling van een innovatie kan 50% van de ontwikkelkosten worden gefinancierd met een krediet van UCF.$$, 'inline'),
  ('db0c8124-244e-4ce8-b71a-1be84081b853', '663bed8f-bd15-4790-b859-567143ef4e08', $$econoom Van Arnhem: positief effect op productiestructuur, risico's voor gepensioneerden$$,
   $$economie-vwo-2017-ii-innovatief-krediet-context4.png$$,
   $$Econoom Paul van Arnhem bekijkt het initiatief van de pensioenfondsen vanuit een maatschappelijk oogpunt. Hij signaleert de volgende aspecten: “Aan de ene kant hebben de plannen om innovatieve bedrijven te financieren een positief effect op de ontwikkeling van de productiestructuur. Aan de andere kant betekenen deze plannen risico’s voor gepensioneerden.”$$, 'inline'),
  ('35726c27-f6c1-4414-b263-54c65579d796', '5afb713d-89cb-4581-8248-9324a541e4e9', $$inleiding: pensioensompolis van ABC, 4% rendement, kosten en winst$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context1.png$$,
   $$Beleggingsmaatschappij ABC overweegt om een pensioensompolis aan te bieden: klanten leggen eenmalig een bedrag in en krijgen daarvoor op hun 65e jaar 100.000 euro uitgekeerd. Afhankelijk van de looptijd wordt het in te leggen bedrag bepaald. ABC verwacht het ingelegde kapitaal te kunnen beleggen tegen gemiddeld 4% rendement per jaar. Uit het verschil tussen de eindwaarde van de beleggingen en het uit te keren bedrag van 100.000 euro worden de kosten gedekt die ABC gedurende de looptijd heeft gemaakt voor de betreffende polis. Het resterende deel is winst. De kosten van een pensioensompolis zijn afhankelijk van de looptijd. Tabel 1 geeft een overzicht van inlegbedrag en kosten, afhankelijk van de looptijd.$$, 'inline'),
  ('dba87674-ac65-4836-af8c-deb089f57b75', '5afb713d-89cb-4581-8248-9324a541e4e9', $$tabel 1: kosten en inleg per polis afhankelijk van looptijd$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context2.png$$,
   $$Tabel 1 kosten en inleg per polis afhankelijk van looptijd
looptijd in jaren | 35 | 30 | 25 | 20 | 15
in te leggen bedrag in euro''s | 36.000 | 42.000 | 50.000 | 56.000 | 65.000
toegerekende kosten in euro''s per polis (aan het eind van de looptijd) | 17.500 | 15.000 | 12.500 | 10.000 | 7.500$$, 'inline'),
  ('aa47d257-2fb2-4ff5-a31a-521b96118619', '5afb713d-89cb-4581-8248-9324a541e4e9', $$eindwaarde polis met looptijd 30 jaar: € 136.222,70$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context3.png$$,
   $$De eindwaarde van een pensioensompolis voor een looptijd van 30 jaar bedraagt € 136.222,70.$$, 'inline'),
  ('2c057406-03ed-4038-b0e8-37c033811290', '5afb713d-89cb-4581-8248-9324a541e4e9', $$financieel analist verwacht slechts 1,5% rendement$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context4.png$$,
   $$Een financieel analist verwacht dat het rendement op de beleggingen gemiddeld slechts 1,5% zal bedragen.$$, 'inline'),
  ('991f6b71-b90b-41e2-a8ae-c75c978dedf7', '5afb713d-89cb-4581-8248-9324a541e4e9', $$ABC schetst twee oplossingen (I vaste inleg, II hogere inleg)$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context5.png$$,
   $$ABC komt tot de conclusie dat de winstgevendheid van het aanbieden van pensioensompolissen in de knel kan komen en schetst twee mogelijke oplossingen als deze situatie zich zal voordoen: I. Het inlegbedrag blijft vast, waarbij het uit te keren kapitaal in het 65e levensjaar afhankelijk wordt van het rendement op de beleggingen. II. Het in te leggen bedrag wordt zodanig verhoogd dat met de verwachte lagere rendementen het eindbedrag op 100.000 euro kan blijven.$$, 'inline'),
  ('632fa48b-7015-4362-b5dd-5833f5ce0488', '5afb713d-89cb-4581-8248-9324a541e4e9', $$beleggingsgedrag afhankelijk van leeftijd en levensfase; marktonderzoek$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context6.png$$,
   $$Beleggingsgedrag van mensen wordt naar verwachting voor een groot deel bepaald door hun leeftijd en levensfase. Om hierop beter te kunnen inspelen, heeft ABC marktonderzoek verricht naar verwachte verkopen van pensioensompolissen naar looptijd (figuur 1).$$, 'inline'),
  ('476c2495-6415-450c-98e0-761be327acdf', '5afb713d-89cb-4581-8248-9324a541e4e9', $$figuur 1: verwacht aandeel in de verkoop van pensioensompolissen naar looptijd$$,
   $$economie-vwo-2017-ii-zeker-een-ton-context7.png$$,
   $$Figuur 1 verwacht aandeel in de verkoop van pensioensompolissen naar looptijd
Cirkeldiagram met sectoren voor looptijden van 35, 30, 25, 20 en 15 jaar; de sectoren voor 35 en 30 jaar zijn het kleinst.
Legenda: 35 jaar, 30 jaar, 25 jaar, 20 jaar, 15 jaar$$, 'inline'),
  ('fff12986-48da-40f4-b882-976a503cc052', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$inleiding: fysiotherapie in de ziektekostenverzekering; loondienst versus zelfstandig$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context1.png$$,
   $$In een land is fysiotherapie voor iedereen opgenomen in de ziektekostenverzekering. Fysiotherapeuten adviseren over voortzetting van de behandeling, afhankelijk van de verbetering bij de patiënt. De Medische Autoriteit (MA) stelt zich onder meer als taak om het kostenbewustzijn in de gezondheidssector te bewaken. Een econoom doet in opdracht van de MA onderzoek naar de behandelduur bij verschillende fysiotherapeuten van een bepaald type schouderklachten. Hij maakt een vergelijking tussen twee soorten gezondheidscentra:
− Centra waar fysiotherapeuten in loondienst zijn. Zij ontvangen een vast inkomen voor een vooraf vastgesteld aantal afspraken per week.
− Centra met zelfstandige fysiotherapeuten. Van zorgverzekeraars ontvangen zij een vaste totale vergoeding per behandeltraject voor een bepaalde klacht, afhankelijk van het aantal afspraken (tabel 1).$$, 'inline'),
  ('ded1fac9-11e8-42ec-9dbc-7004904a550b', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$tabel 1: totale vergoeding afhankelijk van de behandelduur$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context2.png$$,
   $$Tabel 1 totale vergoeding, afhankelijk van de behandelduur
Aantal afspraken | 1-5 | 6-11 | 12-16 | 17 of meer
vergoeding voor het totale traject | € 120 | € 340 | € 560 | € 750
Voorbeeld: Bij een behandeling van veertien afspraken ontvangt de therapeut in totaal een vergoeding van € 560.$$, 'inline'),
  ('ffb81743-f7b4-4e3e-ab32-dbde0a2ce39a', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$econoom: financiële motieven bij zelfstandige fysiotherapeuten; figuur 1$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context3.png$$,
   $$De econoom veronderstelt dat zelfstandige fysiotherapeuten bij het advies over voortzetting van de behandeling, financiële motieven een rol laten spelen. Met behulp van figuur 1 analyseert hij bij hoeveel procent van de patiënten een behandeling met een bepaald aantal afspraken voorkomt.$$, 'inline'),
  ('e3255e31-5ffa-4f74-9d42-5359bd7ff60f', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$figuur 1: frequentie van afspraken bij zelfstandige fysiotherapeuten$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context4.png$$,
   $$Figuur 1 frequentie van afspraken bij zelfstandige fysiotherapeuten
Lijngrafiek: patiënten (%) (0-16) tegen aantal afspraken (1-20); pieken bij 6 afspraken (14%) en bij 12 afspraken (10%), dal bij 11 afspraken; vanaf 15 afspraken constant laag.
Voorbeeld: Een behandeling van acht afspraken komt voor bij 6% van de patiënten.$$, 'inline'),
  ('c415b7dd-9980-49de-92d4-b8a270e5c202', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$vermoeden: prikkel tot langer en tot korter behandelen$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context5.png$$,
   $$De combinatie van tabel 1 en figuur 1 doet de econoom vermoeden dat het bekostigingssysteem bij zelfstandige fysiotherapeuten zowel een prikkel bevat tot langer behandelen als een prikkel tot korter behandelen.$$, 'inline'),
  ('39efb8b0-d395-4ae9-b8b7-d801f02f115f', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$tabel 2: frequentie van afspraken, gegroepeerd naar behandelduur$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context6.png$$,
   $$Tabel 2 frequentie van afspraken, gegroepeerd naar behandelduur
aantal afspraken | 1-5 | 6-11 | 12-16 | ≥ 17
bij zelfstandige therapeuten
% van de patiënten | 14 | 39 | 24 | 23
gemiddeld aantal afspraken | 4,9 | 7,6 | 12,9 | 22
bij therapeuten in loondienst
% van de patiënten | 22 | 41 | 14 | 23
gemiddeld aantal afspraken | 4,4 | 8,1 | 13,4 | 22$$, 'inline'),
  ('f5a76332-eb2a-484a-b1c5-1d11abdb3206', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$conclusie: gemiddeld aantal afspraken bij zelfstandigen hoger$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context7.png$$,
   $$De econoom concludeert uit tabel 2 dat het gemiddelde aantal afspraken bij zelfstandige fysiotherapeuten per saldo hoger ligt dan bij fysiotherapeuten in loondienst.$$, 'inline'),
  ('8699c7ac-f66d-4e45-aad4-63e2994b8ba5', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$voorstel MA: eigen risico per afspraak met lagere premie$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context8.png$$,
   $$Om ervoor te zorgen dat patiënten niet meer behandelingen krijgen dan nodig, stelt de MA voor om, in combinatie met een verlaging van de premie, patiënten een eigen risico te laten betalen in de vorm van een vast bedrag per afspraak. De MA verwacht dat daarmee het gemiddelde aantal afspraken beter zal aansluiten bij wat patiënten nodig hebben.$$, 'inline'),
  ('d96d48d3-f804-495e-9a64-258315854cc1', '6db30926-8ce1-4b40-8351-0b8babf8cdce', $$econoom: sommige patiënten krijgen minder zorg dan nodig$$,
   $$economie-vwo-2017-ii-zwakste-schouders-zwaarste-lasten-context9.png$$,
   $$De econoom voorspelt dat het voorstel van de MA ertoe zal kunnen leiden dat sommige patiënten minder zorg krijgen dan zij behoeven.$$, 'inline');

